import json
import re


def contains(text, phrase):
    return re.search(r"(?<!\w){}(?!\w)".format(re.escape(phrase)), text, re.IGNORECASE) is not None


def step(view, state):
    state.setdefault("visited_locations", [])
    state.setdefault("opened_containers", [])
    state.setdefault("placed_target_objects", [])
    state.setdefault("carrying_target", False)

    objective = view["objective"] or view["observation"]
    match = re.search(
        r"\bput\s+(?:(?:one|two|three|\d+)\s+)?(.+?)\s+(?:in|on|into)\s+(.+?)(?:[.!?]|\n|$)",
        objective,
        re.IGNORECASE,
    )
    commands = view["admissible_commands"]
    choices = commands
    if match:
        target_object = match.group(1).strip().lower()
        target_receptacle = match.group(2).strip().lower()

        if view["history"]:
            previous = view["history"][-1]["action"]
            lowered = previous.lower()
            if lowered.startswith("go to "):
                location = lowered[6:].strip()
                if location not in state["visited_locations"]:
                    state["visited_locations"].append(location)
            elif lowered.startswith("open "):
                if lowered not in state["opened_containers"]:
                    state["opened_containers"].append(lowered)

            taken = re.match(r"^take\s+(.+?)\s+from\s+", previous, re.IGNORECASE)
            if taken and contains(taken.group(1), target_object):
                state["carrying_target"] = True
                state["visited_locations"] = []

            placed = re.match(r"^(?:move|put)\s+(.+?)\s+(?:to|in|on|into)\s+(.+)$", previous, re.IGNORECASE)
            if placed and contains(placed.group(1), target_object) and contains(placed.group(2), target_receptacle):
                item = placed.group(1).strip().lower()
                if item not in state["placed_target_objects"]:
                    state["placed_target_objects"].append(item)
                state["carrying_target"] = False
                state["visited_locations"] = []

        def not_placed(command):
            return not any(contains(command, item) for item in state["placed_target_objects"])

        takes = [
            command for command in commands
            if command.lower().startswith("take ") and contains(command, target_object) and not_placed(command)
        ]
        placements = [
            command for command in commands
            if command.lower().startswith(("move ", "put "))
            and contains(command, target_object)
            and contains(command, target_receptacle)
            and not_placed(command)
        ]
        if state["carrying_target"]:
            choices = placements or [
                command for command in commands
                if command.lower().startswith("go to ") and contains(command, target_receptacle)
            ]
        else:
            choices = takes or placements

        if not choices:
            opens = [
                command for command in commands
                if command.lower().startswith("open ") and command.lower() not in state["opened_containers"]
            ]
            travels = [
                command for command in commands
                if command.lower().startswith("go to ")
                and command[6:].strip().lower() not in state["visited_locations"]
                and not contains(command, target_receptacle)
            ]
            choices = opens + travels
        if not choices:
            raise ValueError("no task-directed legal actions remain")

    if len(choices) == 1:
        return {"kind": "action", "action": choices[0], "state": state}

    numbered_choices = [
        str(index) + ": " + command for index, command in enumerate(choices, start=1)
    ]
    messages = [
        {
            "role": "system",
            "content": "You control ALFWorld. Choose one numbered command from the choices. Output only its 1-based option number.",
        },
        {
            "role": "user",
            "content": json.dumps(
                {
                    "objective": view["objective"],
                    "observation": view["observation"],
                    "recent_history": view["history"][-5:],
                    "choices": numbered_choices,
                    "knowledge": view["knowledge"],
                    "remaining_steps": view["remaining_steps"],
                },
                ensure_ascii=False,
            ),
        },
    ]
    state["action_choices"] = choices
    return {"kind": "model", "messages": messages, "state": state}
